{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "नैमिश नगर में अभी आवेदन कैसे करें?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "पहले चरण के 1,673 भूखंडों का पंजीकरण 24 सितंबर से 24 अक्टूबर 2026 तक registration.ldalucknow.in पर चल रहा है। ₹1,100 की बुकलेट लें और भूखंड की कीमत का 5% (आरक्षित श्रेणी के लिए 2.5%) जमा करें। योजना क्षेत्र के आसपास निजी जमीन खरीदनी हो तो पहले उसका सत्यापन जरूर कराएं।"
      }
    },
    {
      "@type": "Question",
      "name": "नैमिश नगर में भूखंड की कीमत कितनी है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "एलडीए ने नैमिश नगर की दर ₹3,800 प्रति वर्गफुट तय की है। उदाहरण के लिए 112.5 वर्ग मीटर (करीब 1,211 वर्गफुट) का भूखंड करीब ₹46 लाख का होगा। कॉर्नर, पार्क-फेसिंग और फ्रीहोल्ड (12%) जैसे शुल्क अलग हैं।"
      }
    },
    {
      "@type": "Question",
      "name": "नैमिश नगर योजना कब लॉन्च हुई?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "योजना 24 सितंबर 2026 को वरुण विहार योजना के साथ लॉन्च हुई। फरवरी 2026 में अप्रैल में भूमि पूजन और मई से पंजीकरण की योजना थी, लेकिन लॉन्च कई बार टला।"
      }
    },
    {
      "@type": "Question",
      "name": "पंजीकरण की आखिरी तारीख क्या है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "पंजीकरण की आखिरी तारीख 24 अक्टूबर 2026 है। आवंटन की तारीख एलडीए बाद में घोषित करेगा।"
      }
    },
    {
      "@type": "Question",
      "name": "क्या यह लैंड पूलिंग योजना है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "नहीं, नैमिश नगर लैंड पूलिंग योजना नहीं है। एलडीए सहमति-आधारित अधिग्रहण (बैनामे) के माध्यम से किसानों से सीधे जमीन खरीद रहा है। आईटी सिटी और वेलनेस सिटी में लैंड पूलिंग है, नैमिश नगर में नहीं।"
      }
    },
    {
      "@type": "Question",
      "name": "खरीदने से पहले क्या सावधानियां बरतें?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "हमेशा खतौनी सत्यापित करें, एन्कम्ब्रांस चेक करें, और वकील की सलाह लें। योजना क्षेत्र में एलडीए जमीन खरीद रहा है, इसलिए सतर्क रहें।"
      }
    },
    {
      "@type": "Question",
      "name": "कितने गांवों की जमीन शामिल है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "कुल 18 गांव। मूल 14 गांव: भौली, लक्ष्मीपुर, पूरब गांव, पुरवा, सैरपुर, फर्रुखाबाद, कोड़री भौली, कमलाबाद, कमलापुर, पलहरी, गोपरामऊ, बारूमऊ, धतिंगरा और सैदापुर। अगस्त 2025 में सड़कों के लिए पश्चिम गांव, धोबैला, उमरभारी और दुग्गौर जोड़े गए।"
      }
    }
  ]
}
